'use strict';
/* Same-origin client. Financial calculations and permission checks live on the server. */
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const preferences={get(key){try{return localStorage.getItem(key)}catch{return null}},set(key,value){try{localStorage.setItem(key,value)}catch{/* Optional display preference only. */}}};
const icons={grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',store:'M3 9l2-6h14l2 6M4 9v12h16V9M3 9c0 4 5 4 5 0 0 4 4 4 4 0 0 4 4 4 4 0 0 4 5 4 5 0M9 21v-7h6v7',orders:'M7 3h10v4H7zM7 5H4v16h16V5h-3M8 12h8M8 16h6',profit:'M3 17l6-6 4 4 8-11M15 4h6v6M3 21h18',target:'M21 12a9 9 0 1 1-9-9M17 12a5 5 0 1 1-5-5M12 12l9-9M17 3h4v4',truck:'M1 5h13v12H1zM14 9h5l4 5v3h-9M4 17a3 3 0 1 0 6 0M16 17a3 3 0 1 0 6 0',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M17 4a4 4 0 0 1 0 7M22 21v-2a4 4 0 0 0-3-3.87',task:'M9 11l3 3L22 4M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11',report:'M14 2H6a2 2 0 0 0-2 2v16h16V8zM14 2v6h6M8 12h8M8 16h8',sync:'M20 7a9 9 0 0 0-15-3L2 7M2 2v5h5M4 17a9 9 0 0 0 15 3l3-3M22 22v-5h-5',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',shield:'M12 2l9 4v6c0 5-9 10-9 10S3 17 3 12V6zM8 12l3 3 5-6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',audit:'M9 3h6v4H9zM9 5H5v16h14V5h-4M8 11h8M8 15h8',plus:'M12 5v14M5 12h14',arrow:'M5 12h14M14 7l5 5-5 5',chevron:'M9 5l7 7-7 7',down:'M12 3v12M7 10l5 5 5-5M4 17v4h16v-4',moon:'M21 13a9 9 0 0 1-10-10 9 9 0 1 0 10 10',logout:'M9 21H3V3h6M16 17l5-5-5-5M21 12H9',search:'M21 21l-6-6M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14',check:'M5 12l4 4L19 6',alert:'M12 3L2 21h20zM12 9v5M12 17h.01',clock:'M12 8v5l3 2M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18',wallet:'M3 5h17v15H3zM3 5V3h14v2M15 10h6v5h-6z',menu:'M3 6h18M3 12h18M3 18h18',screen:'M2 3h20v14H2zM8 21h8M12 17v4',link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.grid}"/></svg>`;
const state={me:null,stores:[],view:'overview',month:new Date().toLocaleDateString('en-CA',{year:'numeric',month:'2-digit'}).slice(0,7),currency:'',store:'',q:'',page:1,overview:null,epoch:0,notifications:[],wizard:null};
// Date format is explicit, independent of the browser's en-CA implementation.
state.month=`${new Date().getFullYear()}-${String(new Date().getMonth()+1).padStart(2,'0')}`;
const money=(v,c='GBP')=>v===null||v===undefined?'Not verified':new Intl.NumberFormat('en-GB',{style:'currency',currency:c,maximumFractionDigits:2}).format(Number(v));
const percent=v=>v===null||v===undefined?'No target':`${Number(v).toFixed(1).replace(/\.0$/,'')}%`;
const dt=t=>t?new Date(t*1000).toLocaleString('en-GB',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}):'Not connected';
const monthLabel=()=>new Date(state.month+'-02T12:00:00').toLocaleDateString('en-GB',{month:'long',year:'numeric'});
const has=p=>state.me?.permissions.includes('*')||state.me?.permissions.includes(p);
const owner=()=>state.me?.user.role==='owner';
function toast(message,type='info'){const d=document.createElement('div');d.className='toast '+type;d.textContent=String(message);$('#toasts').append(d);setTimeout(()=>d.remove(),7000)}
function errorText(data){if(typeof data?.detail==='string')return data.detail;if(Array.isArray(data?.detail))return data.detail.map(x=>x.loc.join('.')+': '+x.msg).join('\n');return data?.detail?.message||'The request could not be completed.'}
async function api(path,options={}){const {raw=false,noReauth=false,...opts}=options;const headers={...(opts.headers||{})};if(opts.method&&opts.method!=='GET'){headers['Content-Type']='application/json';headers['X-Xcomify-Request']='1';if(state.me?.csrf)headers['X-CSRF-Token']=state.me.csrf}const response=await fetch('/api'+path,{credentials:'same-origin',...opts,headers});if(response.status===428&&!noReauth){await reauthenticate();return api(path,{...options,noReauth:true})}if(!response.ok){const body=await response.json().catch(()=>({detail:'Unexpected response.'}));if(response.status===401&&state.me){state.me=null;renderAuth(false)}throw new Error(errorText(body))}if(raw)return response;return response.json()}
let lastCelebrationCheck=0;
async function checkMilestones(){if(!has('finance:view')||Date.now()-lastCelebrationCheck<10000)return;lastCelebrationCheck=Date.now();try{const data=await post('/celebrations/claim');for(const event of data.events){toast(event.title,'success');if(event.level===100&&!matchMedia('(prefers-reduced-motion: reduce)').matches){for(let i=0;i<28;i++){const piece=document.createElement('i');piece.className='confetti';piece.style.left=(i/28*100)+'vw';piece.style.animationDelay=(Math.random()*.4)+'s';piece.style.transform='rotate('+(Math.random()*180)+'deg)';document.body.append(piece);setTimeout(()=>piece.remove(),3300)}}}}catch{/* A decoration must never block operational data. */}}
const post=(path,body={})=>api(path,{method:'POST',body:JSON.stringify(body)});
const patch=(path,body)=>api(path,{method:'PATCH',body:JSON.stringify(body)});
function reauthenticate(){return new Promise((resolve,reject)=>{const d=$('#reauth-modal'),f=$('#reauth-form');f.reset();$('#reauth-error').textContent='';$('#reauth-code-label').classList.toggle('hidden',!state.me?.user.mfa_enabled);d.showModal();const cancel=()=>{d.close();reject(new Error('Verification cancelled. No sensitive action was performed.'))};$('#reauth-cancel').onclick=cancel;d.oncancel=ev=>{ev.preventDefault();cancel()};f.onsubmit=async ev=>{ev.preventDefault();const b=$('button[type=submit]',f);b.disabled=true;try{await api('/auth/reauth',{method:'POST',body:JSON.stringify({password:f.password.value,code:f.code.value}),noReauth:true});state.me=await api('/me');f.reset();d.close();resolve()}catch(err){$('#reauth-error').textContent=err.message}finally{b.disabled=false}}})}
function modal(title,content,onSubmit){$('#modal-title').textContent=title;$('#modal-content').innerHTML=content;const d=$('#modal');if(!d.open)d.showModal();const f=$('form',$('#modal-content'));if(f&&onSubmit)f.onsubmit=async ev=>{ev.preventDefault();const submit=$('button[type=submit]',f);if(submit)submit.disabled=true;try{await onSubmit(new FormData(f),f)}catch(err){toast(err.message,'error')}finally{if(submit)submit.disabled=false}};setTimeout(()=>$('input:not([type=hidden]),select,textarea',d)?.focus(),40)}
function closeModal(){$('#modal').close();$('#modal-content').innerHTML='';state.wizard=null}
const modalForm=(body,label='Save changes')=>`<form class="modal-form"><div class="modal-body">${body}</div><div class="modal-foot"><button class="button" type="button" data-action="close-modal">Cancel</button><button class="button primary" type="submit">${e(label)}</button></div></form>`;
const textField=(label,name,value='',type='text',extra='')=>`<label>${e(label)}<input type="${type}" name="${name}" value="${e(value)}" ${extra}></label>`;
const selectField=(label,name,options,value='')=>`<label>${e(label)}<select name="${name}">${options.map(([v,t])=>`<option value="${e(v)}" ${String(v)===String(value)?'selected':''}>${e(t)}</option>`).join('')}</select></label>`;
const stateBadge=(label,tone)=>`<span class="status-label ${tone||(['confirmed','succeeded','active','done'].includes(label)?'success':['failed','conflict','outcome_unknown'].includes(label)?'danger':['pending','queued','proposed','paused'].includes(label)?'warning':'neutral')}">${e(label.replaceAll('_',' '))}</span>`;
const empty=(title,description,button='')=>`<div class="card empty">${icon('store')}<h2>${e(title)}</h2><p>${e(description)}</p>${button}</div>`;
const btn=(label,action,ico='',extra='',cls='')=>`<button class="button ${cls}" data-action="${action}" ${extra}>${ico?icon(ico):''}${e(label)}</button>`;
const initial=name=>name.split(' ').filter(Boolean).slice(0,2).map(s=>s[0]).join('').toUpperCase();
function ring(value,small=false){const n=Number(value||0),fill=Math.max(0,Math.min(100,n));return `<div class="ring-wrap ${small?'small':''}"><svg class="ring ${n>=100?'green':''}" viewBox="0 0 148 148" aria-label="${e(percent(value))} target achieved"><circle class="track" cx="74" cy="74" r="62"/><circle class="fill" cx="74" cy="74" r="62" stroke-dasharray="389.56" style="--ring-end:${389.56*(1-fill/100)};stroke-dashoffset:${389.56*(1-fill/100)}"/></svg><div class="ring-label"><strong>${e(percent(value))}</strong><span>of profit target</span></div></div>`}
function navItems(){const out=[['overview','Overview','grid'],['stores','Stores','store'],['orders','Orders','orders']];if(has('finance:view'))out.push(['finance','Profit & reconciliation','profit'],['targets','Profit targets','target']);out.push(['tracking','Tracking monitor','truck']);if(['owner','admin','manager'].includes(state.me.user.role))out.push(['team','Team & access','users']);out.push(['tasks','Tasks','task']);if(has('reports:export'))out.push(['reports','Reports','report']);if(has('sync:run'))out.push(['sync','Sync & conflicts','sync']);out.push(['notifications','Notifications','bell']);if(has('audit:view'))out.push(['audit','Audit trail','audit']);out.push(['security','Security','shield']);if(owner())out.push(['settings','Settings & connections','settings']);return out}
function renderShell(){const nav=navItems();$('#app').innerHTML=`<aside class="sidebar"><div class="brand"><div class="brand-mark">X</div><div><div class="brand-name">xcomify<span class="positive">.</span></div><div class="brand-sub">CENTRAL COMMAND</div></div></div><nav aria-label="Main navigation"><div class="nav-label">WORKSPACE</div>${nav.map(([key,label,i],idx)=>`${idx===7?'<div class="nav-label">MANAGEMENT</div>':''}<button class="nav-button ${state.view===key?'active':''}" data-view="${key}">${icon(i)}<span>${label}</span>${key==='notifications'&&state.notifications.filter(n=>!n.read).length?`<span class="pill-number">${state.notifications.filter(n=>!n.read).length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-foot"><div class="row"><span class="secure-dot"></span><span style="font-size:10px">Private workspace</span></div><p>${state.me.demo?'Isolated demo environment':'Your data. Your permissions.'}<br>Local-first edition &middot; v1.0</p></div></aside><div class="main-shell"><header class="topbar"><div class="row"><button class="icon-button mobile-menu" data-action="menu" aria-label="Toggle navigation">${icon('menu')}</button><div class="breadcrumb">Workspace <span style="margin:0 11px">/</span> <strong>${e(nav.find(n=>n[0]===state.view)?.[1]||'Overview')}</strong></div></div><div class="top-actions"><span class="status-label ${state.me.emergency_stop?'neutral':'warning'}">${state.me.emergency_stop?'Outbound writes stopped':'Outbound writes eligible'}</span><button class="icon-button" data-action="theme" aria-label="Toggle light and dark theme">${icon('moon')}</button><button class="icon-button" data-view="notifications" aria-label="Open notifications">${icon('bell')}</button><div class="avatar">${e(initial(state.me.user.name))}</div><div class="user-summary"><strong>${e(state.me.user.name)}</strong><br><small>${e(state.me.user.role)}</small></div><button class="icon-button" data-action="logout" aria-label="Sign out">${icon('logout')}</button></div></header>${state.me.demo?'<div class="demo-strip"><span><strong>DEMO WORKSPACE</strong> &nbsp; Synthetic orders and amounts. No real eBay or Google account connected.</span><span>Google writes disabled</span></div>':''}<main class="workspace" id="content" tabindex="-1"><div class="loading"><span class="spinner"></span>Loading authorized data...</div></main></div>`;document.body.classList.toggle('dark',preferences.get('xcomify-theme')==='dark')}
function pageHead(title,subtitle,actions='',filters=true){return `<div class="page-head"><div><span class="eyebrow">${e(state.me.workspace)} / CENTRAL COMMAND</span><h1>${title}</h1><p>${e(subtitle)}</p></div><div class="controls">${filters?`<input class="control" id="period-select" type="month" value="${state.month}" aria-label="Reporting month"><select class="control" id="currency-select" aria-label="Reporting currency">${[...new Set(state.stores.map(s=>s.currency))].sort().map(c=>`<option value="${c}" ${c===state.currency?'selected':''}>${c}</option>`).join('')}</select>`:''}${actions}</div></div>`}
function storeOptions(localOnly=false){return state.stores.filter(s=>!localOnly||s.source==='local').map(s=>[s.id,s.name+' ('+s.currency+')'])}
function storeFilter(){return `<select class="control" id="store-select" aria-label="Filter store"><option value="">All assigned stores</option>${state.stores.map(s=>`<option value="${s.id}" ${s.id===state.store?'selected':''}>${e(s.name)}</option>`).join('')}</select>`}
function query(extra={}){return new URLSearchParams(Object.fromEntries(Object.entries({month:state.month,store_id:state.store,...extra}).filter(([,v])=>v!==''&&v!==null&&v!==undefined))).toString()}
async function refreshData(){[state.me,state.stores,state.notifications]=await Promise.all([api('/me'),api('/stores'),api('/notifications')]);if(!state.currency||!state.stores.some(s=>s.currency===state.currency))state.currency=state.stores.some(s=>s.currency==='GBP')?'GBP':state.stores[0]?.currency||'GBP'}
async function navigate(view=state.view){state.view=view;state.page=1;state.q='';await loadView(true)}
async function loadView(shell=false){const epoch=++state.epoch;try{if(shell){await refreshData();renderShell()}const html=await views[state.view]();if(epoch===state.epoch&&$('#content')){$('#content').innerHTML=html;document.title=`${navItems().find(x=>x[0]===state.view)?.[1]||'Workspace'} | Xcomify`;void checkMilestones()}}catch(err){if($('#content'))$('#content').innerHTML=`<div class="page-error">${e(err.message)}<div style="margin-top:12px">${btn('Try again','refresh','sync')}</div></div>`;else toast(err.message,'error')}}
function stat(label,value,foot,i='wallet',tone=''){return `<div class="card stat"><div class="stat-top"><span>${e(label)}</span><span class="stat-icon">${icon(i)}</span></div><div class="stat-value ${tone}">${e(value)}</div><div class="stat-bottom">${e(foot)}</div></div>`}
function chart(stores,currency){const series={};stores.forEach(s=>(s.daily||[]).forEach(x=>series[x.date]=(series[x.date]||0)+Number(x.profit)));const keys=Object.keys(series).sort();if(!keys.length)return '<div class="chart-empty">A profit trend appears when complete records are available.</div>';let accumulated=0;const vals=keys.map(k=>({date:k,value:accumulated+=series[k]}));const min=Math.min(0,...vals.map(x=>x.value)),max=Math.max(1,...vals.map(x=>x.value)),range=max-min||1;const x=i=>52+(vals.length===1?0:i/(vals.length-1))*726,y=v=>160-((v-min)/range)*135;const line=vals.map((v,i)=>(i?'L':'M')+x(i).toFixed(2)+' '+y(v.value).toFixed(2)).join(' ');const grid=[0,.33,.66,1].map(r=>{const yy=160-r*135;return `<line class="grid-line" x1="50" y1="${yy}" x2="790" y2="${yy}"/><text x="1" y="${yy+4}">${e(new Intl.NumberFormat('en-GB',{notation:'compact',maximumFractionDigits:1}).format(min+r*range))}</text>`}).join('');return `<svg class="profit-chart" viewBox="0 0 810 195" role="img" aria-label="Cumulative eligible profit in ${currency}">${grid}<path class="area" d="${line} L${x(vals.length-1)} 160 L52 160 Z"/><path class="line" d="${line}"/>${[0,Math.floor((vals.length-1)/2),vals.length-1].filter((v,i,a)=>a.indexOf(v)===i).map(i=>`<text x="${x(i)}" y="186" text-anchor="middle">${e(keys[i].slice(8))} ${e(new Date(keys[i]+'T12:00:00').toLocaleDateString('en-GB',{month:'short'}))}</text>`).join('')}</svg>`}
function storeCard(s,manage=false){const st=state.stores.find(x=>x.id===s.store_id)||{},ach=Number(s.attainment||0),unverified=s.eligible_profit===null;return `<article class="card store-card"><div class="between"><div class="row"><div class="store-badge">${e(s.marketplace||st.marketplace)}</div><div><div class="store-name">${e(s.store)}</div><div class="store-meta">${e(s.currency)} &middot; ${s.source==='google'?'Google Sheets':'Local records'} ${state.me.demo?'&middot; DEMO':''}</div></div></div>${stateBadge(s.incomplete_orders?'Review costs':ach>=100?'Target reached':s.status==='paused'?'Paused':'Active',ach>=100?'success':s.incomplete_orders?'warning':'neutral')}</div><div class="store-profit">${e(money(s.eligible_profit,s.currency))}</div><div class="store-target">${unverified?'Approve the financial basis to verify profit':`of ${e(money(s.target,s.currency))} monthly profit target`}</div><div class="progress-line ${ach>=100?'achieved':''}"><span style="width:${Math.max(0,Math.min(100,ach))}%"></span></div><div class="progress-meta"><strong>${e(percent(s.attainment))} achieved</strong><span>${s.remaining!==null&&s.remaining!==undefined?e(money(s.remaining,s.currency))+' to go':'Target not set'}</span></div><div class="store-footer"><span>${s.orders} orders &middot; ${s.incomplete_orders||0} need review</span>${manage&&owner()?btn('Manage','edit-store','',`data-id="${s.store_id}"`,'small ghost'):btn('View target','view-target','chevron',`data-id="${s.store_id}"`,'small ghost')}</div>${manage?`<div class="row wrap" style="margin-top:12px">${owner()?btn('Sheet mapping','mapping','link',`data-id="${s.store_id}" ${state.me.demo?'disabled title="Live Sheets are disabled in demo"':''}`,'small'):''}${st.source==='google'&&has('sync:run')?btn('Sync now','sync-store','sync',`data-id="${s.store_id}"`,'small'):''}${st.source==='google'&&owner()?btn('Write gate','write-gate','shield',`data-id="${s.store_id}"`,'small'):''}</div>`:''}</article>`}
const views={};
views.overview=async()=>{const d=await api('/overview?'+query({currency:state.currency}));state.overview=d;const g=d.groups.length===1?d.groups[0]:null;const finance=d.finance_visible;const eligible=d.stores.filter(x=>x.financial_approved);const totalTarget=g?Number(g.target):0;return pageHead('Your business, in one view.','Profit, progress and the work that needs your attention.',btn('Refresh','refresh','sync'))+(!d.stores.length?empty('Your workspace is ready','Add your first eBay store, then connect its private Google Sheet. No sample records are mixed into this workspace.',owner()?btn('Add your first store','add-store','plus','','primary'):''): `<div class="stats">${stat(finance?'Eligible profit':'Assigned stores',finance?(g?money(g.profit,g.currency):'Grouped by basis'):String(d.active_stores),finance?'Confirmed inputs only. Not audited accounts.':'Visible within your store permissions','wallet')}${stat('Net order earnings',finance?(g?money(g.earnings,g.currency):'See grouped reports'):'Restricted','Already-net earnings, not gross sales','profit')}${stat('Orders this month',d.total_orders,`${d.active_stores} active store${d.active_stores===1?'':'s'}`,'orders')}${stat(finance?'Profit target':'Source records',finance?(g?money(g.target,g.currency):'By store'):'Operational',finance?`${g?percent(g.attainment):'Separate'} across compatible targets`:'Source Sheet remains authoritative','target')}</div>${finance?`<div class="dashboard-main"><section class="card card-pad"><div class="card-head"><div><h2>Profit performance</h2><p>Cumulative confirmed subtotal &middot; ${e(monthLabel())}</p></div><span class="status-label neutral">${e(state.currency)} only</span></div><div class="chart-value">${g?e(money(g.profit,g.currency)):'Separate profit bases'}</div><div class="chart-meta"><span class="dot"></span>Complete records, excluding provisional profit</div>${d.groups.length<=1?chart(eligible,state.currency):'<div class="chart-empty">Different profit bases are not merged. Open Profit &amp; reconciliation.</div>'}<div class="chart-caption"><span>Store currencies are never mixed without approved FX.</span><span>${d.stores.length} stores in view</span></div></section><aside class="card pace-card"><div class="card-head"><h2>Monthly target</h2>${icon('target')}</div>${ring(g?.attainment)}<div class="pace-numbers"><div><span>Eligible profit</span><strong>${g?e(money(g.targeted_profit,g.currency)):'By store'}</strong></div><div><span>Monthly goal</span><strong>${g?e(money(g.target,g.currency)):'By store'}</strong></div></div><div class="note ${d.missing_cost_or_issues?'warning':'blue'}">${d.missing_cost_or_issues?`${d.missing_cost_or_issues} records need financial review. Incomplete records cannot trigger a target celebration.`:totalTarget?'Every step counts. Track the remaining daily profit in each store target.':'Set a monthly profit target for each account to start tracking progress.'}</div></aside></div>`:''}<div class="section-head"><div><h2>Store performance</h2><p>Independent targets. A clear view of every account.</p></div>${btn('All stores','goto-stores','arrow','','ghost')}</div><div class="store-grid">${d.stores.map(s=>finance?storeCard(s):`<div class="card card-pad"><h3>${e(s.store)}</h3><p>${s.orders} orders</p><p class="subtle">Financial values are restricted by role.</p></div>`).join('')}</div><div class="bottom-grid"><section class="card card-pad"><div class="card-head"><h2>Needs your attention</h2>${icon('alert')}</div><div class="attention-row"><div class="attention-icon">${icon('wallet')}</div><div class="attention-copy"><strong>${d.missing_cost_or_issues} incomplete financial records</strong><p>Missing or unverified inputs are not treated as zero.</p></div>${has('costs:view')?btn('Review','goto-finance','','','small'):''}</div><div class="attention-row"><div class="attention-icon">${icon('sync')}</div><div class="attention-copy"><strong>${d.stores.filter(x=>x.source==='google'&&x.stale).length} connected stores need a fresh scan</strong><p>Local records do not claim a Google sync timestamp.</p></div>${has('sync:run')?btn('Sync monitor','goto-sync','','','small'):''}</div></section><section class="card card-pad"><div class="card-head"><h2>Workspace safeguards</h2>${icon('shield')}</div><div class="security-item">${icon('check')}<div><strong>${state.me.emergency_stop?'Outbound write-stop is on':'Controlled writes are eligible'}</strong><small>Proposals, approvals and verification stay separate.</small></div></div><div class="security-item">${icon('shield')}<div><strong>${state.me.user.mfa_enabled?'MFA is enabled':'Add authenticator protection'}</strong><small>${state.me.user.mfa_enabled?'Admin write gates require a verified session.':'Required before approving live Google writes.'}</small></div>${!state.me.user.mfa_enabled?btn('Set up','goto-security','','','small'):''}</div></section></div><p class="footnote">View refreshed ${e(dt(d.generated_at))}. Store-local reporting periods apply. ${state.me.demo?'All displayed figures are synthetic examples.':''}</p>`)};
views.stores=async()=>{const d=await api('/overview?'+query({currency:null}));return pageHead('Your stores','Keep every account separate. Manage them from one workspace.',owner()?btn('Add store','add-store','plus','','primary'):'',false)+(!d.stores.length?empty('Add your first store','Existing Google Sheets and extensions stay exactly where they are.',owner()?btn('Create store','add-store','plus','','primary'):''):`<div class="store-grid">${d.stores.map(s=>has('finance:view')?storeCard(s,true):`<div class="card card-pad"><h3>${e(s.store)}</h3><p>${s.orders} orders &middot; ${e(s.currency)}</p></div>`).join('')}</div>`)+`<p class="footnote">Mappings are per file and numeric tab ID. No spreadsheet columns, formulas, sharing permissions or extensions are changed by onboarding.</p>`};
views.orders=async()=>renderOrders(false);views.tracking=async()=>renderOrders(true);
async function renderOrders(tracking){const d=await api('/orders?'+query({q:state.q,page:state.page,attention:tracking?'tracking':null}));return pageHead(tracking?'Tracking monitor':'Order workspace',tracking?'Records without tracking. A tracking value does not prove an eBay upload or delivery.':'Search all authorized stores. Source edits remain traceable.',!tracking&&has('orders:edit')?btn('Add local order','add-order','plus','','primary'):'',false)+`<form class="toolbar" id="order-search">${storeFilter()}<input class="control" type="month" id="period-select" value="${state.month}" aria-label="Order month"><input name="q" class="control search" placeholder="Order ID, tracking, supplier or product" value="${e(state.q)}" aria-label="Search orders"><button class="button" type="submit">${icon('search')}Search</button>${has('costs:view')&&!tracking?btn('Import CSV','csv-import','down') :''}</form>`+(!d.rows.length?empty('No matching orders',state.me.demo?'Try another filter, store or month.':'Connect a private Sheet or add local records to start.'): `<div class="card"><div class="table-scroll"><table><thead><tr><th>Order / store</th><th>Product</th><th>Sold</th>${has('finance:view')?'<th>Net earnings</th><th>Profit</th>':''}<th>Tracking / status</th><th></th></tr></thead><tbody>${d.rows.map(o=>`<tr><td><button class="inline-edit mono" data-action="order" data-id="${o.id}">${e(o.ebay_id)}</button><div class="subtle">${e(o.store)}</div></td><td class="title-cell" title="${e(o.title)}">${e(o.title||'Untitled product')}${o.issues.length?'<div>'+stateBadge('Needs review','warning')+'</div>':''}</td><td>${e(o.sold_on)}</td>${has('finance:view')?`<td>${e(money(o.earnings,o.currency))}</td><td class="${Number(o.profit)<0?'negative':''}">${o.profit===null?stateBadge('Incomplete','warning'):e(money(o.profit,o.currency))}</td>`:''}<td><span class="mono">${e(o.tracking||'Awaiting tracking')}</span><div style="margin-top:4px">${stateBadge(o.status)}</div></td><td>${btn('Open','order','chevron',`data-id="${o.id}"`,'small ghost')}</td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>${d.total} records &middot; Page ${d.page}</span><div class="row">${btn('Previous','prev-page','',d.page<=1?'disabled':'','small')}${btn('Next','next-page','',d.page*d.page_size>=d.total?'disabled':'','small')}</div></div></div>`)}
views.finance=async()=>{const [d,entries,attention]=await Promise.all([api('/overview?'+query({currency:null})),api('/financials/entries?'+query()),has('costs:view')?api('/orders?'+query({attention:'cost',page_size:100})):Promise.resolve({rows:[],total:0})]);return pageHead('Profit & reconciliation','Clear definitions. Complete inputs. No silently invented profit.',has('finance:adjust')?btn('Add adjustment','adjustment','plus','','primary'):'',false)+`<div class="toolbar">${storeFilter()}<input class="control" id="period-select" type="month" value="${state.month}" aria-label="Profit month"></div><div class="note blue" style="margin-bottom:20px">Operational profit = net order earnings - supplier cost - extra expenses - refunds + supplier credits. Filler costs stay excluded unless the owner explicitly enables them. Missing cost is unknown, not zero.</div><div class="stats">${d.groups.map(g=>stat(g.currency+' / '+g.basis.replaceAll('_',' '),money(g.profit,g.currency),`${g.incomplete_orders} incomplete records excluded from eligible profit`,'wallet')).join('')}</div><div class="card"><div class="table-scroll"><table><thead><tr><th>Store</th><th>Complete subtotal</th><th>Provisional subtotal</th><th>Data coverage</th><th>Financial basis</th><th></th></tr></thead><tbody>${d.stores.map(s=>`<tr><td><strong>${e(s.store)}</strong><div class="subtle">${e(s.currency)}</div></td><td>${e(money(s.confirmed_subtotal,s.currency))}</td><td>${e(money(s.provisional_subtotal,s.currency))}</td><td>${s.complete_orders}/${s.orders} complete<br>${stateBadge(s.incomplete_orders?'Review required':'Complete',s.incomplete_orders?'warning':'success')}</td><td>${stateBadge(s.financial_approved?'Owner-approved basis':'Approval required',s.financial_approved?'success':'warning')}<div class="subtle">${e(s.basis?.replaceAll('_',' '))}</div></td><td>${owner()?btn('Review settings','edit-store','',`data-id="${s.store_id}"`,'small'):''}</td></tr>`).join('')||'<tr><td colspan="6">No stores in this view.</td></tr>'}</tbody></table></div></div>${has('costs:view')?`<div class="section-head"><div><h2>Missing financial inputs</h2><p>${attention.total} records with missing cost, missing earnings or unobserved source rows.</p></div></div>${attention.rows.length?`<div class="card"><div class="table-scroll"><table><thead><tr><th>Order</th><th>Store</th><th>Cost</th><th>Source</th><th></th></tr></thead><tbody>${attention.rows.slice(0,20).map(o=>`<tr><td class="mono">${e(o.ebay_id)}</td><td>${e(o.store)}</td><td>${o.cost===null?stateBadge('Missing','warning'):e(money(o.cost,o.currency))}</td><td>${o.observed?'Observed':'Not observed on latest scan'}</td><td>${btn('Review','order','',`data-id="${o.id}"`,'small')}</td></tr>`).join('')}</tbody></table></div></div>`:'<div class="note">No records with these missing inputs in the selected period. Check any formula or duplicate-row flags in the Orders view as well.</div>'}`:''}<div class="section-head"><div><h2>Financial adjustments</h2><p>Append-only entries, with a reason and recognition date.</p></div></div><div class="card table-scroll"><table><thead><tr><th>Date</th><th>Store</th><th>Profit effect</th><th>Reason</th></tr></thead><tbody>${entries.map(x=>{const st=state.stores.find(z=>z.id===x.store_id);return `<tr><td>${e(x.date)}</td><td>${e(st?.name)}</td><td class="${Number(x.amount)<0?'negative':'positive'}">${e(money(x.amount,st?.currency))}</td><td>${e(x.reason)}</td></tr>`}).join('')||'<tr><td colspan="4" class="muted">No additional adjustments in this period.</td></tr>'}</tbody></table></div><p class="footnote">Provisional subtotal is an estimate from available amounts only, not eligible target profit. Currency conversion, audited accounting and tax filing are not implied.</p>`};
views.targets=async()=>{const d=await api('/overview?'+query({currency:null}));state.overview=d;return pageHead('Every store. Its own ambition.','Set individual monthly profit targets and see exactly what remains.',btn('Focus view','focus','screen'),false)+`<div class="toolbar">${storeFilter()}<input class="control" id="period-select" type="month" value="${state.month}" aria-label="Target month"></div>`+(!d.stores.length?empty('Targets begin with a store','Add a store and approve its financial basis before measuring target progress.'): `<div class="store-grid two">${d.stores.map(s=>`<article class="card target-card"><div class="between"><div class="row"><div class="store-badge">${e(s.marketplace)}</div><div><div class="store-name">${e(s.store)}</div><div class="store-meta">${e(monthLabel())} &middot; ${e(s.currency)}</div></div></div>${has('targets:edit')?btn('Edit target','target','',`data-id="${s.store_id}"`,'small'):''}</div><div class="target-center">${ring(s.attainment)}<div class="target-copy"><span>Eligible profit</span><strong>${e(money(s.eligible_profit,s.currency))}</strong><span>Target: ${e(money(s.target,s.currency))}</span>${stateBadge(s.incomplete_orders?'Review required':Number(s.attainment)>=100?'Target reached':s.target==='0.00'?'No target':'In progress',Number(s.attainment)>=100?'success':s.incomplete_orders?'warning':'neutral')}</div></div><div class="target-pace"><div>Remaining profit<strong>${s.remaining===null?'Set a target':e(money(s.remaining,s.currency))}</strong></div><div>Required per remaining day<strong>${s.required_daily_profit===null?'Not available':e(money(s.required_daily_profit,s.currency))}</strong></div><div>Projection from completed days<strong>${s.projected_profit===null?'Insufficient history':e(money(s.projected_profit,s.currency))}</strong></div><div>Days remaining, including today<strong>${s.days_remaining_including_today}</strong></div></div><p class="footnote">${s.incomplete_orders?`${s.incomplete_orders} incomplete records. Target celebrations are held until required inputs are complete.`:s.financial_approved?'Progress follows approved profit, including corrections and refunds.':'Profit basis is not approved; target progress is not certified.'} Projection is a simple daily-rate estimate, not a guarantee.</p></article>`).join('')}</div>`)};
views.team=async()=>{const rows=await api('/team');return pageHead('The right access. For each person.','Store assignments are enforced on the server, not just hidden in the interface.',owner()?btn('Invite team member','invite','plus','','primary'):'',false)+`<div class="card table-scroll"><table><thead><tr><th>Team member</th><th>Role</th><th>Assigned stores</th><th>MFA</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(u=>`<tr><td><div class="row"><div class="avatar">${e(initial(u.name))}</div><div><strong>${e(u.name)}</strong><div class="subtle">${e(u.email)}</div></div></div></td><td>${e(u.role)}</td><td>${u.role==='owner'?'All organization stores':e(u.stores.map(x=>state.stores.find(s=>s.id===x)?.name||'').join(', ')||'No stores assigned')}</td><td>${stateBadge(u.mfa_enabled?'Enabled':'Not enabled',u.mfa_enabled?'success':'warning')}</td><td>${stateBadge(u.active?'active':'deactivated')}</td><td>${owner()&&u.role!=='owner'?btn('Manage','edit-user','',`data-id="${u.id}"`,'small'):''}</td></tr>`).join('')}</tbody></table></div><div class="note" style="margin-top:20px">Operations employees cannot access financial figures. Deactivation or changed assignments revoke all of that user's active sessions. Invitations are copied and delivered privately; this build does not pretend to send email.</div>`};
views.tasks=async()=>{const tasks=await api('/tasks');return pageHead('Team tasks','A shared queue for the work that needs a person.',has('tasks:edit')?btn('New task','new-task','plus','','primary'):'',false)+(!tasks.length?empty('A clear task list','Create a task for an authorized store and assign the right team member.'): `<div class="card table-scroll"><table><thead><tr><th>Task</th><th>Store</th><th>Assigned to</th><th>Due</th><th>Status</th></tr></thead><tbody>${tasks.map(t=>`<tr><td><strong>${e(t.title)}</strong></td><td>${e(state.stores.find(s=>s.id===t.store_id)?.name)}</td><td>${e(t.assignee)}</td><td>${e(t.due_on||'No due date')}</td><td>${has('tasks:edit')?`<select class="control task-status" data-id="${t.id}" aria-label="Task status">${['open','in_progress','done'].map(k=>`<option value="${k}" ${k===t.status?'selected':''}>${e(k.replaceAll('_',' '))}</option>`).join('')}</select>`:stateBadge(t.status)}</td></tr>`).join('')}</tbody></table></div>`)};
views.reports=async()=>{const d=await api('/reports/summary?month='+state.month);return pageHead('Reports you can trace','Store-level figures with financial coverage, currency and source freshness.',btn('Export orders CSV','export-csv','down')+btn('Print report','print','report'))+`<div class="note blue" style="margin-bottom:20px">${e(d.profit_definition)}</div><div class="card card-pad"><div class="card-head"><div><h2>Monthly performance &middot; ${e(monthLabel())}</h2><p>Generated ${e(dt(d.generated_at))}. ${state.me.demo?'Synthetic demonstration data.':'Authorized stores only.'}</p></div></div><div class="table-scroll"><table><thead><tr><th>Store / currency</th><th>Profit basis</th><th>Eligible profit</th><th>Target</th><th>Attainment</th><th>Coverage</th><th>Period</th></tr></thead><tbody>${d.stores.map(s=>`<tr><td><strong>${e(s.store)}</strong><div class="subtle">${e(s.currency)}</div></td><td>${e(s.basis.replaceAll('_',' '))}</td><td>${e(money(s.eligible_profit,s.currency))}</td><td>${e(money(s.target,s.currency))}</td><td>${e(percent(s.attainment))}</td><td>${s.coverage}%<div class="subtle">${s.incomplete_orders} incomplete</div></td><td>${s.closed?stateBadge('Closed','success'):owner()?btn('Close period','close-period','',`data-id="${s.store_id}"`,'small'):stateBadge('Open')}</td></tr>`).join('')||'<tr><td colspan="7">No stores yet.</td></tr>'}</tbody></table></div><p class="footnote">${e(d.fx_policy)} Reporting uses each store's local calendar month. Closing a completed month blocks later direct financial edits; use explained current-period adjustments. CSV export is capped at 10,000 records and protects against spreadsheet-formula injection.</p></div>`};
views.sync=async()=>{const d=await api('/sync');return pageHead('Sync & change control','A proposal is not a write. A submitted write is not yet a verified change.',btn('Refresh','refresh','sync'),false)+`<div class="stats">${stat('Worker',d.worker_alive?'Running':'Not observed','Durable queue, independent of dashboard tab','sync')}${stat('Pending jobs',d.jobs.filter(j=>['pending','running'].includes(j.state)).length,'Jobs persist across server restarts','clock')}${stat('Review needed',d.intents.filter(i=>['conflict','outcome_unknown','failed'].includes(i.state)).length,'No blind replay of ambiguous remote writes','alert')}${stat('Outbound control',state.me.emergency_stop?'Stopped':'Gated','Per-store gates and approvals still apply','shield')}</div><div class="section-head"><div><h2>Write proposals & conflicts</h2><p>Only application-owned existing cells can be written after approval.</p></div></div>${d.intents.length?`<div class="card table-scroll"><table><thead><tr><th>Store / field</th><th>State</th><th>Proposed change</th><th>Review note</th><th>Actions</th></tr></thead><tbody>${d.intents.map(i=>`<tr><td>${e(state.stores.find(s=>s.id===i.store_id)?.name)}<div class="subtle">${e(i.fields.join(', '))}</div></td><td>${stateBadge(i.state)}</td><td class="mono">${i.proposed?e(JSON.stringify(i.proposed)):'Financial details restricted'}</td><td style="max-width:300px">${e(i.error||i.reason)}</td><td><div class="row wrap">${i.state==='proposed'&&has('writes:approve')?btn('Approve','approve-intent','',`data-id="${i.id}"`,'small'):''}${['conflict','outcome_unknown','failed'].includes(i.state)&&owner()?btn('Reconcile','reconcile-intent','',`data-id="${i.id}"`,'small'):''}${!['submitting','verifying','confirmed','cancelled'].includes(i.state)&&has('orders:edit')?btn('Cancel','cancel-intent','',`data-id="${i.id}"`,'small danger'):''}</div></td></tr>`).join('')}</tbody></table></div>`:empty('No outbound changes','Google-connected order edits appear here as proposals. Remote writes stay disabled until your owner completes all release gates.')}<div class="section-head"><div><h2>Recent synchronization jobs</h2><p>Complete scans, retries and errors remain visible.</p></div></div><div class="card table-scroll"><table><thead><tr><th>Store</th><th>Type</th><th>Status</th><th>Attempts</th><th>Result / error</th><th>Updated</th></tr></thead><tbody>${d.jobs.map(j=>`<tr><td>${e(state.stores.find(s=>s.id===j.store_id)?.name)}</td><td>${e(j.kind)}</td><td>${stateBadge(j.state)}</td><td>${j.attempts}</td><td style="max-width:360px">${e(j.error||[j.result?.created!==undefined?j.result.created+' new':'',j.result?.updated!==undefined?j.result.updated+' updated':'',j.result?.errors?.length?j.result.errors.length+' review issues':''].filter(Boolean).join(', ')||'No result yet')}${j.result?.errors?.length?`<details><summary>Source issues</summary><pre class="code-block">${e(JSON.stringify(j.result.errors,null,2))}</pre></details>`:''}</td><td>${e(dt(j.finished_at||j.created_at))}</td></tr>`).join('')||'<tr><td colspan="6" class="muted">No live jobs. Connect a Google Sheet to start read-only synchronization.</td></tr>'}</tbody></table></div><p class="footnote">Polling does not rely on Apps Script edit triggers. A last-moment edit by an independent Sheet writer cannot be eliminated by a read-before-write check; preserve Sheet ownership unless a real single-writer workflow is in place.</p>`};
views.notifications=async()=>{const items=await api('/notifications');state.notifications=items;return pageHead('Notifications','Only alerts from stores you are authorized to access.','',false)+(items.length?`<div class="card">${items.map(n=>`<div class="notification ${n.read?'':'unread'}">${icon(n.severity==='success'?'target':n.severity==='warning'?'alert':'bell')}<div style="flex:1"><strong>${e(n.title)}</strong><p>${e(n.body)}</p><span class="subtle">${e(dt(n.created_at))}</span></div>${!n.read?btn('Mark read','read-notification','check',`data-id="${n.id}"`,'small'):stateBadge('Read','neutral')}</div>`).join('')}</div>`:empty('All clear','Sync issues and confirmed target milestones appear here. No fabricated alerts.'))};
views.audit=async()=>{const d=await api('/audit?page='+state.page);return pageHead('An accountable history','Who changed what, when and why. No secrets in event payloads.','',false)+`<div class="card"><div class="table-scroll"><table><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Store</th><th>Details</th></tr></thead><tbody>${d.rows.map(a=>`<tr><td>${e(dt(a.at))}</td><td>${e(a.actor)}</td><td class="mono">${e(a.action)}</td><td>${e(state.stores.find(s=>s.id===a.store_id)?.name||'Workspace')}</td><td><details><summary>Inspect event</summary><pre class="code-block">${e(JSON.stringify(a.details,null,2))}</pre></details></td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>${d.total} recorded events &middot; Page ${d.page}</span><div class="row">${btn('Previous','prev-page','',d.page===1?'disabled':'','small')}${btn('Next','next-page','',d.page*50>=d.total?'disabled':'','small')}</div></div></div><p class="footnote">${e(d.integrity)} Export to separately controlled storage is part of the production hardening checklist, not an assumed property of this local database.</p>`};
views.security=async()=>{const sessions=await api('/sessions');return pageHead('Security & sessions','Control access to your account and review signed-in devices.',btn('Reauthenticate','reauthenticate','shield'),false)+`<div class="settings-grid"><section class="card card-pad"><div class="card-head"><h2>Authenticator protection</h2>${icon('shield')}</div><div class="value-large">${state.me.user.mfa_enabled?'MFA enabled':'Add a second factor'}</div><p class="muted" style="font-size:12px">TOTP authenticator codes and one-use recovery codes. MFA is required before approving live Google writes.</p>${state.me.user.mfa_enabled?stateBadge('Protected','success'):btn('Set up authenticator','mfa','shield','','primary')}<p class="footnote">No authenticator secrets are sent to a QR-code website. Enter the setup key directly into your trusted authenticator app.</p></section><section class="card card-pad"><div class="card-head"><h2>Password & recovery</h2>${icon('settings')}</div><p class="muted" style="font-size:12px">Use a unique passphrase of at least 14 characters. Changing it revokes all other sessions.</p>${btn('Change password','password','shield')}<div class="note" style="margin-top:20px">There is no public registration or email-reset backdoor. Owner recovery requires access to the deployment host and is documented in the recovery guide.</div></section><section class="card card-pad wide"><div class="card-head"><div><h2>Active sessions</h2><p>Server-side idle and absolute expiry apply.</p></div>${btn('Sign out other devices','revoke-sessions','logout')}</div><div class="table-scroll"><table><thead><tr><th>Device / browser</th><th>Signed in</th><th>Last activity</th><th>Session</th></tr></thead><tbody>${sessions.map(s=>`<tr><td style="max-width:420px;overflow-wrap:anywhere">${e(s.device)}</td><td>${e(dt(s.created_at))}</td><td>${e(dt(s.last_seen))}</td><td>${stateBadge(s.current?'Current':'Other',s.current?'success':'neutral')}</td></tr>`).join('')}</tbody></table></div></section></div>`};
views.settings=async()=>{const [sys,connections]=await Promise.all([api('/system/status'),api('/connections')]);return pageHead('Settings & connections','Private integrations, recovery controls and a visible system status.','',false)+`<div class="settings-grid"><section class="card card-pad"><div class="card-head"><h2>Google Sheets</h2>${icon('link')}</div><p class="muted" style="font-size:12px">Authorize your own Google identity. Keep operational spreadsheets Restricted. No marketplace passwords are collected.</p>${btn('Authorize Google','google-connect','link',state.me.demo?'disabled title="Disabled in the isolated demo"':'','primary')}<p class="footnote">${sys.google_configured?'OAuth client configured. Select your authorized Google account.':'OAuth client not configured. Add your client ID and secret to the private environment, then restart. See docs/GOOGLE_SETUP.md.'}</p>${connections.map(c=>`<div class="security-item"><div style="flex:1"><strong>${e(c.name)}</strong><small>${c.active?'Connected':'Disconnected'} &middot; ${e(dt(c.created_at))}</small></div>${c.active?btn('Disconnect','disconnect','',`data-id="${c.id}"`,'small danger'):''}</div>`).join('')}</section><section class="card card-pad"><div class="card-head"><h2>Emergency write-stop</h2>${icon('shield')}</div><div class="value-large">${sys.emergency_stop?'Outbound writes stopped':'Write gates active'}</div><p class="muted" style="font-size:12px">Stop new Google mutations while retaining safe read access. An already-submitted request may still complete.</p>${btn(sys.emergency_stop?'Clear global stop':'Stop outbound writes','write-stop','shield',state.me.demo&&sys.emergency_stop?'disabled title="Demo writes remain permanently blocked"':'',sys.emergency_stop?'':'danger')}<p class="footnote">Clearing the stop does not bypass individual store gates, field ownership, MFA, approvals or read-back verification.</p></section><section class="card card-pad"><div class="card-head"><h2>Encrypted backup</h2>${icon('down')}</div><p class="muted" style="font-size:12px">${state.me.local_database?'Create an encrypted snapshot of the local workspace, including the key required to recover its encrypted integration credentials.':'PostgreSQL deployments require your external encrypted backups and point-in-time recovery setup.'}</p>${state.me.local_database?btn('Create & download backup','backup','down'):''}<p class="footnote">Last backup: ${sys.last_backup?e(dt(sys.last_backup.at)):'No backup recorded'}. Store <span class="mono">backup-recovery.key</span> separately from the encrypted backup. Restoration uses an empty directory and forces writes off.</p></section><section class="card card-pad"><div class="card-head"><h2>System status</h2>${icon('settings')}</div><div class="security-item"><div><strong>${e(sys.database)}</strong><small>Persistent application data</small></div></div><div class="security-item"><div><strong>${sys.worker_alive?'Worker is running':'Worker not observed'}</strong><small>${sys.pending_jobs} pending or active jobs</small></div></div><div class="security-item"><div><strong>No public registration</strong><small>Same-origin API &middot; server-side permissions</small></div></div><div class="security-item"><div><strong>Release ${e(sys.version)}</strong><small>Local-first functional build</small></div></div></section><section class="card card-pad wide"><h2>Deployment readiness</h2><p class="muted" style="font-size:12px">${e(sys.release_status)}</p><div class="note">This working edition uses FastAPI, SQLAlchemy and a durable database queue. SQLite makes a single-PC launch straightforward; a PostgreSQL deployment profile is included. The earlier Next.js/NestJS stack was not retained. Advanced AI, direct marketplace actions, scheduled outbound email and public client portals are not silently simulated.</div><div class="row wrap" style="margin-top:15px">${btn('Download API schema','openapi','report')}${btn('Focus view','focus','screen')}</div></section></div>`};
