function reasonDialog(title,description,submit,label='Confirm',extra=''){modal(title,modalForm(`<p class="muted">${e(description)}</p>${extra}<label>Reason<textarea name="reason" required minlength="8" maxlength="1000" placeholder="Explain this action for the audit history"></textarea></label>`,label),async(fd,f)=>{await submit(fd,f);closeModal();await loadView(true)})}
function dateToday(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
actions['add-store']=()=>modal('Add an eBay store',modalForm(`<div class="note blue" style="margin-bottom:20px">This creates a private store workspace. No eBay account login or Google Sheet modification is performed.</div><div class="form-grid">${textField('Store name','name','','text','required maxlength="120"')}${selectField('Marketplace','marketplace',[['UK','United Kingdom'],['AU','Australia'],['US','United States'],['DE','Germany'],['CA','Canada'],['Other','Other']],'UK')}${selectField('Store currency','currency',[['GBP','GBP - British pound'],['AUD','AUD - Australian dollar'],['USD','USD - US dollar'],['EUR','EUR - Euro'],['CAD','CAD - Canadian dollar']],'GBP')}${selectField('Reporting timezone','timezone',[['Europe/London','Europe/London'],['Australia/Sydney','Australia/Sydney'],['America/New_York','America/New_York'],['Europe/Berlin','Europe/Berlin'],['America/Toronto','America/Toronto'],['Asia/Karachi','Asia/Karachi']],'Europe/London')}</div>`,'Create store'),async fd=>{await post('/stores',Object.fromEntries(fd));closeModal();toast('Store created. Your existing Sheets are unchanged.','success');await navigate('stores')});
actions['edit-store']=async el=>{await refreshData();const st=state.stores.find(x=>x.id===el.dataset.id);modal('Manage '+st.name,modalForm(`<div class="form-grid">${textField('Store name','name',st.name,'text','required maxlength="120"')}${selectField('Marketplace','marketplace',['UK','AU','US','DE','CA','Other'].map(x=>[x,x]),st.marketplace)}${selectField('Currency (cannot relabel existing orders)','currency',['GBP','AUD','USD','EUR','CAD'].map(x=>[x,x]),st.currency)}${textField('IANA reporting timezone','timezone',st.timezone,'text','required')}${selectField('Store status','status',[['active','Active'],['paused','Paused'],['archived','Archived']],st.status)}${textField('Sync interval in seconds','poll_seconds',st.poll_seconds,'number','min="60" max="3600" required')}</div><div class="form-section-title">Approve your financial definition</div><div class="note warning">Use net order earnings already after marketplace fees. Supplier costs, extra expenses, refunds and credits must only include amounts not already represented in those earnings. This approval is your financial-definition decision, not an accounting audit.</div><label class="check"><input type="checkbox" name="financial_approved" ${st.financial_approved?'checked':''}>I have verified these field meanings and approve this profit basis for targets.</label><label class="check"><input type="checkbox" name="include_filler" ${st.include_filler?'checked':''}>Include recorded filler-item cost in profit. Leave unchecked to preserve target-item operational profit.</label><p class="help">Changing financial settings may change calculated progress. No milestone celebration is manufactured by this settings revision.</p>`),async fd=>{const b=Object.fromEntries(fd);b.revision=st.revision;b.poll_seconds=Number(b.poll_seconds);b.financial_approved=fd.has('financial_approved');b.include_filler=fd.has('include_filler');await patch('/stores/'+st.id,b);closeModal();toast('Store settings saved and audited.','success');await loadView(true)})};
actions.target=async el=>{const st=state.stores.find(x=>x.id===el.dataset.id),s=await api(`/stores/${st.id}/summary?month=${state.month}`);modal('Set profit target',modalForm(`<div class="note blue" style="margin-bottom:18px">${e(st.name)} &middot; ${e(monthLabel())} &middot; ${e(st.currency)}<br>Target uses the store's approved profit basis, not gross revenue.</div>${textField('Monthly target ('+st.currency+')','amount',s.target,'number','min="0" step="0.01" required')}<label>Reason for setting or revising<textarea name="reason" required minlength="4" maxlength="500" placeholder="For example: November operating target"></textarea></label><p class="help">Zero means no active target. Target revisions are recorded and do not replay old milestone celebrations.</p>`,'Save profit target'),async fd=>{await post(`/stores/${st.id}/targets`,{month:state.month,amount:fd.get('amount'),version:s.target_version,reason:fd.get('reason')});closeModal();toast('Profit target saved.','success');await loadView(true)})};
actions['add-order']=()=>{const local=storeOptions(true);if(!local.length){toast('Add a local store first. Google-connected rows should be created through the existing Sheet workflow.','error');return}modal('Add a local order',modalForm(`<div class="note" style="margin-bottom:18px">Database record only. This does not purchase a product, append a Sheet row or contact eBay.</div><div class="form-grid">${selectField('Local store','store_id',local,state.store)}${textField('Exact eBay order ID','ebay_id','','text','required maxlength="100"')}${textField('Sold date (store local)','sold_on',dateToday(),'date','required')}${textField('Product title','title','','text','maxlength="2000"')}${has('costs:view')?textField('Net order earnings','earnings','','number','step="0.01"')+textField('Supplier cost (blank = unknown)','cost','','number','step="0.01" min="0"'):''}${textField('AliExpress reference','supplier_ref','','text','maxlength="150"')}${textField('Tracking number','tracking','','text','maxlength="200"')}${textField('Postcode for verified matching','postcode','','text','maxlength="30"')}${selectField('Operational status','status',[['New','New'],['Placed','Placed'],['Tracking available','Tracking available'],['Cancelled','Cancelled']])}</div>`,'Save local order'),async fd=>{const b=Object.fromEntries(fd),id=b.store_id;delete b.store_id;if('earnings'in b)b.earnings=b.earnings||null;if('cost'in b)b.cost=b.cost||null;await post('/stores/'+id+'/orders',b);closeModal();toast('Local order saved.','success');await loadView(true)})};
actions.order=async el=>{const o=await api('/orders/'+el.dataset.id);const editFields=[['notes','Internal note (database only)'],['tracking','Tracking number'],['courier','Courier'],['supplier_ref','Supplier reference'],['status','Operational status']];if(has('costs:view'))editFields.push(['cost','Supplier cost'],['extra','Extra expense not already deducted'],['refund','Refund not already deducted'],['credit','Supplier credit'],['filler','Excluded filler cost']);if(o.origin==='local'&&has('costs:view'))editFields.push(['earnings','Net order earnings'],['sold_on','Sold date'],['title','Product title'],['postcode','Postcode']);const body=`<div class="between"><div><span class="mono">${e(o.ebay_id)}</span><h3 style="margin-top:5px">${e(o.title)}</h3><p class="subtle">${e(o.store)} &middot; ${e(o.sold_on)} &middot; ${e(o.origin)} record</p></div>${stateBadge(o.status)}</div><div class="detail-grid">${[['Net earnings',o.earnings===undefined?'Restricted':money(o.earnings,o.currency)],['Supplier cost',o.cost===undefined?'Restricted':o.cost===null?'Missing':money(o.cost,o.currency)],['Order profit',o.profit===undefined?'Restricted':o.profit===null?'Incomplete':money(o.profit,o.currency)],['Supplier reference',o.supplier_ref||'Not recorded'],['Tracking',o.tracking||'Not available'],['Postcode',o.postcode||'Not recorded']].map(([l,v])=>`<div><span>${e(l)}</span><strong>${e(v)}</strong></div>`).join('')}</div>${o.issues.length?`<div class="note warning">${o.issues.map(e).join('<br>')}</div>`:''}${o.notes?`<div class="note">${e(o.notes)}</div>`:''}${o.pending.length?`<p class="help">Pending proposals: ${o.pending.map(x=>e(x.fields.join(', '))+' ('+e(x.state)+')').join('; ')}</p>`:''}${has('orders:edit')?`<div class="divider"></div><div class="form-section-title">Make one traceable change</div>${selectField('Field','field',editFields,'notes')}<label>New value<textarea name="value" id="order-new-value" maxlength="4000">${e(o.notes||'')}</textarea></label><label>Reason<textarea name="reason" required minlength="4" maxlength="1000" placeholder="Why is this record changing?"></textarea></label><div class="note ${o.origin==='google'?'warning':''}">${o.origin==='google'?'Mapped Google fields create a proposal only. The current confirmed value remains unchanged until an approved write is verified. Internal notes remain database-only.':'Local records update with a revision check. Financial edits require recent identity verification.'}</div>`:''}`;modal('Order details',has('orders:edit')?modalForm(body,'Save change / proposal'):`<div class="modal-body">${body}</div>`,async fd=>{const field=fd.get('field'),value=fd.get('value');const changed={};changed[field]=['cost','earnings'].includes(field)&&value===''?null:value;const r=await patch('/orders/'+o.id,{revision:o.revision,changes:changed,reason:fd.get('reason'),idempotency_key:crypto.randomUUID()});closeModal();toast(r.state==='proposed'?'Proposal saved. No Google cell changed.':'Change confirmed.','success');await loadView(true)});const select=$('[name=field]',$('#modal-content'));if(select)select.onchange=()=>{$('#order-new-value').value=o[select.value]??''}};
actions.adjustment=()=>modal('Append a profit adjustment',modalForm(`${selectField('Store','store_id',storeOptions(),state.store)}<div class="form-grid">${textField('Profit effect (negative for an expense)','amount','','number','step="0.01" required')}${textField('Recognition date','recognized_on',dateToday(),'date','required')}</div><label>Reason and evidence reference<textarea name="reason" required minlength="8" maxlength="1000" placeholder="Explain the adjustment and its source. Do not enter secrets or buyer addresses."></textarea></label><div class="note warning">This is an additional entry, not a second deduction of an amount already in order earnings. Closed periods cannot be changed.</div>`,'Record adjustment'),async fd=>{const b=Object.fromEntries(fd),id=b.store_id;delete b.store_id;b.idempotency_key=crypto.randomUUID();await post('/stores/'+id+'/adjustments',b);closeModal();toast('Adjustment recorded with source reason.','success');await loadView(true)});
