actions['csv-import']=()=>{if(!storeOptions(true).length){toast('CSV import requires a local store.','error');return}modal('Import local order records',`<form class="modal-form"><div class="modal-body">${selectField('Local store','store_id',storeOptions(true),state.store)}<p class="help">Use column names from the template. Dates: YYYY-MM-DD. Amounts: 12.50, without currency symbols. Blank cost remains unknown. Duplicate IDs are rejected, not overwritten.</p><div class="row wrap" style="margin-bottom:15px">${btn('Download blank template','csv-template','down')}<input type="file" id="csv-file" accept=".csv,text/csv" aria-label="Select CSV file"></div><label>CSV content<textarea name="csv_text" id="csv-text" class="mono" required style="min-height:140px"></textarea></label><div id="csv-preview" class="help"></div></div><div class="modal-foot"><button class="button" type="button" data-action="preview-csv">Preview import</button><button class="button primary" type="submit">Validate & import</button></div></form>`,async fd=>{const r=await post('/stores/'+fd.get('store_id')+'/csv-import',{csv_text:fd.get('csv_text'),commit:true});closeModal();toast(r.valid_rows+' orders imported. Initial milestones were not celebrated.','success');await loadView(true)});$('#csv-file').onchange=async ev=>{const f=ev.target.files[0];if(f){if(f.size>2_000_000){toast('Maximum CSV size is 2 MB.','error');return}$('#csv-text').value=await f.text()}}};
