actions['new-task']=async()=>{const users=await api('/team').catch(()=>[{id:state.me.user.id,name:state.me.user.name}]);modal('Create a task',modalForm(`${selectField('Store','store_id',storeOptions(),state.store)}${textField('Task','title','','text','required minlength="3" maxlength="200"')}${selectField('Assign to','assignee_id',[['','Unassigned'],...users.filter(u=>u.active!==false).map(u=>[u.id,u.name])],state.me.user.id)}${textField('Due date (optional)','due_on','','date')}`,'Create task'),async fd=>{const b=Object.fromEntries(fd);b.assignee_id=b.assignee_id||null;b.due_on=b.due_on||null;await post('/tasks',b);closeModal();toast('Task created.','success');await loadView(true)})};
actions.mfa=async()=>{const setup=await post('/auth/mfa/setup');modal('Set up your authenticator',modalForm(`<div class="note blue">In your authenticator, choose Add account / Enter setup key. Type: time-based (TOTP), 6 digits, 30 seconds.</div><label style="margin-top:18px">Account<input readonly value="${e(state.me.user.email)}"></label><label>Private setup key<input id="copy-value" readonly class="mono" value="${e(setup.secret)}"></label>${btn('Copy setup key','copy-value','link')}<p class="help">Keep this secret private. It is never sent to an external QR website.</p>${textField('Current six-digit authenticator code','code','','text','required inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code"')}`,'Enable authenticator'),async fd=>{const r=await post('/auth/mfa/confirm',{code:fd.get('code')});state.me=await api('/me');modal('Save your recovery codes',`<div class="modal-body"><div class="note warning">Each code works once. Save them offline now; they are not shown again. Anyone with a code and your password can sign in.</div><textarea id="copy-value" class="mono" readonly style="min-height:210px;margin:18px 0">${e(r.recovery_codes.join('\n'))}</textarea>${btn('Copy recovery codes','copy-value','down','','primary')}</div>`);toast('MFA enabled. Other sessions were revoked.','success');await loadView(true)})};
