actions.disconnect=el=>reasonDialog('Disconnect Google locally','The saved integration credential is erased and connected stores lose write permission. Revoke the external grant in Google account permissions separately.',async fd=>{await post('/connections/'+el.dataset.id+'/disconnect',{reason:fd.get('reason')});toast('Local Google credential erased.','success')},'Disconnect');
actions.backup=async()=>{const r=await api('/system/backup',{method:'POST',body:'{}',raw:true});const name=(r.headers.get('content-disposition')||'').match(/filename="?([^";]+)"?/)?.[1]||'xcomify-backup.xcbak';downloadBlob(await r.blob(),name);toast('Encrypted backup created. Keep backup-recovery.key separately.','success');await loadView(true)};
actions['write-gate']=el=>{const st=state.stores.find(x=>x.id===el.dataset.id);const checks=[['single_writer_confirmed','I enforce a single-writer workflow for each app-owned cell, including independent extensions/editors.'],['mapping_verified','I verified file ID, numeric tab ID, headers and exact order/postcode matching.'],['private_sharing_verified','Google sharing remains Restricted and authorized.'],['test_sheet_write_verified','I tested write and read-back against an isolated authorized Google test sheet.'],['extension_regression_verified','I regression-tested the actual existing extensions on a safe copy.'],['restore_verified','I performed and verified a backup restore drill.'],['limited_rollout_approved','I approve this limited-store rollout.']];modal('Live write gate: '+st.name,modalForm(`<div class="note warning">Do not tick checks that have not actually been performed. The app records owner attestations, not an independent certification. Read-only sync and financial approval must already pass.</div><label class="check"><input type="checkbox" name="enabled" ${st.writes_enabled?'checked':''}>Enable controlled outbound writes for this store.</label>${checks.map(([k,t])=>`<label class="check"><input name="${k}" type="checkbox" ${st.gates?.[k]?'checked':''}>${e(t)}</label>`).join('')}<label>Reason / test evidence reference<textarea name="reason" required minlength="8" maxlength="1000"></textarea></label>`,'Save write gate'),async fd=>{const b={enabled:fd.has('enabled'),reason:fd.get('reason')};checks.forEach(([k])=>b[k]=fd.has(k));await post('/stores/'+st.id+'/write-enable',b);closeModal();toast('Store write gate recorded. Global write-stop may still be on.','success');await loadView(true)})};
const fieldLabels={ebay_id:'eBay order ID (required)',sold_on:'Sold date (required)',earnings:'Net order earnings (required)',cost:'Supplier purchase cost (required)',title:'Product title',supplier_ref:'AliExpress reference',tracking:'Tracking number',courier:'Courier',postcode:'Postcode',status:'Status',extra:'Extra expense',refund:'Refund not already deducted',credit:'Supplier credit',filler:'Excluded filler cost'};
actions.mapping=async el=>{const st=state.stores.find(x=>x.id===el.dataset.id),connections=(await api('/connections')).filter(x=>x.active);if(!connections.length){modal('Connect your Google identity first',`<div class="modal-body"><p class="muted">Set your own OAuth client credentials in the private environment, authorize Google in Settings, then return to map this store. No secrets should be pasted into chat.</p>${btn('Open settings','modal-settings','settings','','primary')}</div>`);return}state.wizard={store:st,headers:[]};modal('Map your existing Sheet',`<form class="modal-form" id="mapping-form"><div class="modal-body"><div class="note blue" style="margin-bottom:18px">No columns, formulas, extension code or sharing settings will be changed. Saving schedules a read-only import.</div>${selectField('Google connection','connection_id',connections.map(c=>[c.id,c.name]),st.connection_id)}${textField('Spreadsheet ID (the /d/ ID, not a sharing URL)','spreadsheet_id',st.spreadsheet_id||'','text','required pattern="[A-Za-z0-9_-]{20,180}"')}${btn('Inspect file','inspect-file','search')}<div id="sheet-options" style="margin-top:18px"></div><div id="mapping-columns"></div><div id="mapping-result"></div></div><div class="modal-foot"><button class="button" type="button" data-action="preview-mapping">Preview import</button><button class="button primary" type="submit">Save mapping & queue import</button></div></form>`,async()=>{const b=mappingPayload();await post('/stores/'+st.id+'/mapping',b);closeModal();toast('Mapping saved. Read-only import queued; write-back remains disabled.','success');await loadView(true)})};
actions['modal-settings']=async()=>{closeModal();await navigate('settings')};
actions['inspect-file']=async()=>{const f=$('#mapping-form');const data=await api('/connections/'+f.connection_id.value+'/metadata?spreadsheet_id='+encodeURIComponent(f.spreadsheet_id.value));state.wizard.file=data;$('#sheet-options').innerHTML=`<div class="note">${e(data.properties?.title)} &middot; Source locale: ${e(data.properties?.locale)} &middot; Source timezone: ${e(data.properties?.timeZone)}</div><div class="form-grid" style="margin-top:15px">${selectField('Exact tab (numeric ID)','sheet_id',data.sheets.map(s=>[s.properties.sheetId,s.properties.title+' [ID '+s.properties.sheetId+']']),state.wizard.store.sheet_id??data.sheets[0]?.properties.sheetId)}${textField('Header row','header_row',state.wizard.store.header_row||1,'number','min="1" max="100" required')}${selectField('Source date format','date_format',[['day_first','Day / month / year'],['month_first','Month / day / year'],['iso','ISO year-month-day']],state.wizard.store.mapping?.date_format||'day_first')}${textField('Approved full grid scan row cap','max_rows',state.wizard.store.max_rows||10000,'number','min="100" max="50000" required')}</div>${btn('Load column headers','load-columns','orders')}`;$('#mapping-columns').innerHTML='';state.wizard.headers=[]};
actions['load-columns']=async()=>{const f=$('#mapping-form');const d=await api(`/connections/${f.connection_id.value}/sample?`+new URLSearchParams({spreadsheet_id:f.spreadsheet_id.value,sheet_id:f.sheet_id.value,header_row:f.header_row.value}));state.wizard.headers=d.headers;const existing=state.wizard.store.mapping?.fields||{};$('#mapping-columns').innerHTML=`<div class="form-section-title">Verify every column yourself</div>${d.dynamic_formula?'<div class="note warning">Dynamic/array formulas detected. This adapter conservatively blocks write-back anywhere in the tab.</div>':''}<div class="table-scroll"><table class="mapping-table"><thead><tr><th>Application field</th><th>Existing column header</th><th>Field ownership</th></tr></thead><tbody>${Object.entries(fieldLabels).map(([k,label])=>`<tr><td>${e(label)}</td><td><select name="map_${k}" ${['ebay_id','sold_on','earnings','cost'].includes(k)?'required':''}><option value="">Not mapped</option>${d.headers.map(h=>`<option value="${h.column}" ${existing[k]?.column===h.column?'selected':''}>${e(h.header)} (column ${h.column+1})</option>`).join('')}</select></td><td><select name="owner_${k}"><option value="sheet">Sheet / extension owned</option><option value="computed" ${existing[k]?.ownership==='computed'?'selected':''}>Computed / read-only</option>${['cost','extra','refund','credit','filler','supplier_ref','tracking','courier','status'].includes(k)?`<option value="app" ${existing[k]?.ownership==='app'?'selected':''}>App-owned existing cells</option>`:''}</select></td></tr>`).join('')}</tbody></table></div><p class="help">Selecting app-owned does not enable writes. Prove a single-writer workflow and pass the separate write gate first. Default Sheet ownership preserves your existing extensions.</p>`};
function mappingPayload(){const f=$('#mapping-form'),headers=state.wizard?.headers;if(!headers?.length)throw new Error('Inspect the file and load its column headers first.');const fields={};Object.keys(fieldLabels).forEach(k=>{const v=f.elements['map_'+k]?.value;if(v!==''&&v!==undefined){const h=headers.find(x=>x.column===Number(v));fields[k]={column:Number(v),header:h.header,ownership:f.elements['owner_'+k].value}}});return {connection_id:f.connection_id.value,spreadsheet_id:f.spreadsheet_id.value,sheet_id:Number(f.sheet_id.value),header_row:Number(f.header_row.value),fields,date_format:f.date_format.value,max_rows:Number(f.max_rows.value)}}
actions['preview-mapping']=async()=>{const b=mappingPayload(),r=await post('/stores/'+state.wizard.store.id+'/mapping-preview',b);$('#mapping-result').innerHTML=`<div class="note ${r.errors.length?'warning':'blue'}" style="margin-top:18px">${r.orders} canonical orders &middot; ${r.rows} observed rows &middot; ${r.errors.length} issues. No writes performed.</div><pre class="code-block">${e(JSON.stringify(r.errors.length?r.errors:r.sample,null,2))}</pre>`};
function renderAuth(setup,inviteToken=''){document.body.classList.remove('office');$('.focus-exit')?.remove();$('#app').innerHTML=`<div class="auth-screen"><section class="auth-art"><div class="brand"><div class="brand-mark">X</div><div><div class="brand-name">xcomify.</div><div class="brand-sub">CENTRAL COMMAND</div></div></div><div class="orb"></div><div class="hero-text"><div class="eyebrow">ONE WORKSPACE. EVERY STORE.</div><h1 style="margin-top:18px">Know your numbers.<br>Reach your next goal.</h1><p>A private command center for your stores, your profit targets and the team behind them.</p></div><div class="auth-footer subtle">Private by default &nbsp;&middot;&nbsp; Your existing workflows, preserved</div></section><section class="auth-form-side"><form class="auth-form" id="auth-form"><span class="eyebrow">${state.demoMode?'ISOLATED SYNTHETIC DEMO':'PRIVATE BUSINESS WORKSPACE'}</span><h1 style="margin-top:12px">${inviteToken?'Accept your invitation':setup?'Make this workspace yours.':'Welcome back.'}</h1><p>${inviteToken?'Create a passphrase for the account your owner invited.':setup?'No default password. Use the setup code displayed in your server window to create the first owner.':'Sign in to your authorized Xcomify workspace.'}</p>${setup||inviteToken?textField('Your name','name','','text','required minlength="2" maxlength="120" autocomplete="name"'):''}${!inviteToken?textField('Email address','email','','email','required maxlength="254" autocomplete="username"'):''}${textField(setup||inviteToken?'Create a passphrase (14+ characters)':'Password','password','','password',`required ${setup||inviteToken?'minlength="14"':''} maxlength="256" autocomplete="${setup||inviteToken?'new-password':'current-password'}"`)}${setup?textField('One-time setup code from server window','setup_code','','password','required autocomplete="off" minlength="20"') :inviteToken?'':`<div id="login-mfa" class="hidden">${textField('Authenticator or recovery code','code','','text','autocomplete="one-time-code" maxlength="80"')}</div>`}<p id="auth-error" class="form-error" role="alert"></p><button type="submit" class="button primary">${inviteToken?'Join workspace':setup?'Create owner account':'Sign in securely'} ${icon('arrow')}</button><p class="footnote">${state.demoMode?'All demo records are synthetic. Google connections and remote writes are disabled.':'Buyer data and integration credentials stay on your chosen host. Public registration is disabled.'}</p></form></section></div>`;$('#auth-form').onsubmit=async ev=>{ev.preventDefault();const f=ev.currentTarget,b=$('button[type=submit]',f);b.disabled=true;$('#auth-error').textContent='';try{let payload=Object.fromEntries(new FormData(f));if(inviteToken){payload.token=inviteToken;await post('/invitations/accept',payload);history.replaceState(null,'','/')}else await post(setup?'/setup':'/auth/login',payload);state.me=await api('/me');await navigate('overview')}catch(err){if(err.message.startsWith('MFA_REQUIRED')){$('#login-mfa')?.classList.remove('hidden');$('#auth-error').textContent='Enter the current authenticator code or a recovery code.';$('[name=code]',f)?.focus()}else $('#auth-error').textContent=err.message}finally{b.disabled=false}}}
document.addEventListener('click',async ev=>{const view=ev.target.closest('[data-view]');if(view){await navigate(view.dataset.view);return}const target=ev.target.closest('[data-action]');if(!target||target.disabled)return;const fn=actions[target.dataset.action];if(!fn)return;try{target.classList.add('loading-button');await fn(target)}catch(err){toast(err.message,'error')}finally{target.classList.remove('loading-button')}});
document.addEventListener('change',async ev=>{const t=ev.target;try{if(t.id==='period-select'){state.month=t.value;state.page=1;await loadView()}else if(t.id==='currency-select'){state.currency=t.value;await loadView()}else if(t.id==='store-select'){state.store=t.value;state.page=1;await loadView()}else if(t.classList.contains('task-status')){await patch('/tasks/'+t.dataset.id,{status:t.value});toast('Task updated.','success')}}catch(err){toast(err.message,'error')}});
document.addEventListener('submit',async ev=>{if(ev.target.id==='order-search'){ev.preventDefault();state.q=ev.target.q.value;state.page=1;await loadView()}});
async function boot(){try{const status=await api('/setup/status');state.demoMode=status.demo;const token=location.hash.startsWith('#invite=')?location.hash.slice(8):'';if(token){renderAuth(false,token);return}if(!status.configured){renderAuth(true);return}try{state.me=await api('/me')}catch{renderAuth(false);return}if(location.hash.startsWith('#google=')){toast(location.hash.endsWith('connected')?'Google connected. Now map a store to its file and tab.':'Google authorization cancelled.');history.replaceState(null,'','/');state.view='settings'}await loadView(true)}catch(err){$('#app').innerHTML=`<div class="boot"><div class="brand-mark">X</div><h1>Workspace unavailable</h1><p>${e(err.message)}</p><p>Start the included server launcher, then open its localhost address.</p></div>`}}
setInterval(async()=>{if(!state.me||document.hidden||$('#modal').open||$('#reauth-modal').open||!['overview','targets','sync'].includes(state.view))return;try{await loadView()}catch{}},30000);
boot();
